let data=load(),historyFilter='Alle',installPrompt=null,cloudClient=null,cloudUser=null,cloudVersion=null,cloudSaveTimer=null,cloudSaving=false,cloudReady=false,activeProfileName=localStorage.getItem(`grevingfit-profile:${localStorage.getItem(CLOUD_OWNER_KEY)}`)||'',sessionDraft=null,spotifyAccessToken='',spotifyTokenExpires=0,spotifyPlayer=null,spotifyDeviceId='',spotifySdkLoaded=false,spotifyPlaybackStatus='Nicht verbunden';
function normalizeData(saved={}){const {activeDay,...state}=saved||{},catalog=(Array.isArray(saved.catalog)?saved.catalog:structuredClone(seed.catalog)).map(item=>{const {rest,...entry}=item;return {...entry,group:muscleGroups.includes(entry.group)?entry.group:'Sonstige'}}),plan=(Array.isArray(saved.plan)?saved.plan:structuredClone(seed.plan)).map(({day,...w})=>({...w,exercises:(w.exercises||[]).map(({rest,...exercise})=>exercise)}));return {...structuredClone(seed),...state,catalog,plan,history:Array.isArray(saved.history)?saved.history:[]}}
function load(){try{return normalizeData(JSON.parse(localStorage.getItem(KEY)||'{}'))}catch{return normalizeData()}}
function freshData(){return normalizeData({catalog:structuredClone(seed.catalog),plan:structuredClone(seed.plan),history:[]})}
function save(){localStorage.setItem(KEY,JSON.stringify(data));if(cloudUser)localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));if(cloudUser||localStorage.getItem(CLOUD_OWNER_KEY)){localStorage.setItem(CLOUD_DIRTY_KEY,'1');if(cloudUser){clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(cloudSaveNow,900)}}}
const $=(sel,root=document)=>root.querySelector(sel), $$=(sel,root=document)=>[...root.querySelectorAll(sel)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function storedCloudConfig(){return {...CLOUD_DEFAULT_CONFIG}}
function createCloudClient(config){if(!window.supabase?.createClient)throw Error('Die Supabase-Bibliothek konnte nicht geladen werden. Prüfe die Internetverbindung.');if(!/^https?:\/\//i.test(config.url)||!config.key)throw Error('Bitte trage Projekt-URL und Publishable Key ein.');cloudClient=window.supabase.createClient(config.url.replace(/\/$/,''),config.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});return cloudClient}
function updateCloudButton(){const button=$('#cloudBtn'),check=$('#cloudCheck'),mark=$('.brand-mark');if(mark)mark.textContent=(activeProfileName||'Carsten').trim().charAt(0).toUpperCase();if(!button)return;const connected=Boolean(cloudUser);if(check)check.hidden=!connected;button.classList.toggle('cloud-connected',connected);button.title=connected?`Cloud verbunden: ${activeProfileName||cloudUser.email||'angemeldet'}`:'Cloud-Synchronisierung einrichten';button.setAttribute('aria-label',button.title)}
async function startCloud(){const config=storedCloudConfig();if(!config.url||!config.key||!window.supabase?.createClient){updateCloudButton();return}try{createCloudClient(config);const {data:result,error}=await cloudClient.auth.getSession();if(error)throw error;const user=result.session?.user;if(user)await activateCloudUser(user,null);updateCloudButton()}catch(error){console.warn('Cloud-Verbindung konnte nicht gestartet werden:',error.message);updateCloudButton()}}
async function cloudFetch(){const {data:row,error}=await cloudClient.from('fitness_data').select('payload,version,updated_at').eq('user_id',cloudUser.id).maybeSingle();if(error)throw error;return row}
function applyCloudRow(row){const incoming=row.payload;if(!incoming||!Array.isArray(incoming.plan)||!Array.isArray(incoming.history))throw Error('Die Cloud-Sicherung enthält kein gültiges GrevingFit-Datenformat.');data=normalizeData(incoming);localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));cloudVersion=Number(row.version);localStorage.setItem(CLOUD_VERSION_KEY,String(cloudVersion));localStorage.setItem(CLOUD_OWNER_KEY,cloudUser.id);localStorage.removeItem(CLOUD_DIRTY_KEY);render();updateCloudButton()}
async function cloudWrite(payload,expectedVersion=null){const now=new Date().toISOString(),values={payload:structuredClone(payload),version:(expectedVersion||0)+1,updated_at:now};let query;if(expectedVersion===null)query=cloudClient.from('fitness_data').insert({user_id:cloudUser.id,...values});else query=cloudClient.from('fitness_data').update(values).eq('user_id',cloudUser.id).eq('version',expectedVersion);const {data:rows,error}=await query.select('version,updated_at').maybeSingle();if(error)throw error;if(!rows)return null;cloudVersion=Number(rows.version);localStorage.setItem(CLOUD_VERSION_KEY,String(cloudVersion));localStorage.setItem(CLOUD_OWNER_KEY,cloudUser.id);localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));localStorage.removeItem(CLOUD_DIRTY_KEY);updateCloudButton();return rows}
async function cloudInitialSync(){if(!cloudClient||!cloudUser||!activeProfileName)return;cloudReady=false;try{const row=await cloudFetch(),owner=localStorage.getItem(CLOUD_OWNER_KEY),sameAccount=owner===cloudUser.id;if(!row){if(owner&&!sameAccount&&!localStorage.getItem(`${KEY}:${cloudUser.id}`)){showEmptyCloudChoices();return}const inserted=await cloudWrite(data,null);if(!inserted)throw Error('Die erste Cloud-Sicherung konnte nicht erstellt werden.');cloudReady=true;toast('Lokale Daten erstmals in der Cloud gesichert');return}const dirty=localStorage.getItem(CLOUD_DIRTY_KEY)==='1';if(!sameAccount||dirty){showCloudChoices(row,!sameAccount?'Diese Cloud enthält bereits Daten. Wähle die Version für '+activeProfileName+'.':'Auf diesem Gerät gibt es noch nicht synchronisierte Änderungen. Wähle die Version, die gelten soll.');return}if(cloudVersion!==Number(row.version)){applyCloudRow(row);toast('Cloud-Daten geladen')}else updateCloudButton();cloudReady=true}catch(error){console.error('Cloud-Synchronisierung fehlgeschlagen:',error);toast(`Cloud-Sync fehlgeschlagen: ${error.message||'Verbindung prüfen'}`)}}
async function cloudSaveNow(){if(!cloudClient||!cloudUser||!cloudReady||cloudSaving||localStorage.getItem(CLOUD_DIRTY_KEY)!=='1')return;cloudSaving=true;try{const saved=await cloudWrite(data,cloudVersion);if(!saved){toast('Cloud-Konflikt: Öffne ☁ und wähle die gewünschte Version.');return}toast('Änderungen in der Cloud gespeichert')}catch(error){console.error('Cloud-Speichern fehlgeschlagen:',error);toast('Cloud-Speichern fehlgeschlagen – lokal bleibt alles erhalten')}finally{cloudSaving=false}}
function showCloudChoices(row,message){const d=modal(`<h2>Cloud-Daten abgleichen</h2><p>${esc(message)}</p><p class="tiny muted">Cloud-Stand: ${new Date(row.updated_at).toLocaleString('de-DE')}</p><div class="grid"><button class="button" type="button" data-cloud-load>Cloud-Daten auf dieses Gerät laden</button><button class="button secondary" type="button" data-cloud-overwrite>Lokale Daten in die Cloud übernehmen</button><button class="button ghost" type="button" data-close>Später entscheiden</button></div>`);$('[data-cloud-load]',d).onclick=()=>{try{applyCloudRow(row);cloudReady=true;d.close();toast('Cloud-Daten geladen')}catch(error){alert(error.message)}};$('[data-cloud-overwrite]',d).onclick=async()=>{try{const saved=await cloudWrite(data,Number(row.version));if(!saved){d.close();showCloudChoices(await cloudFetch(),'Die Cloud wurde zwischenzeitlich geändert. Bitte wähle erneut.');return}cloudReady=true;d.close();toast('Lokale Daten gespeichert')}catch(error){alert(`Cloud-Speichern fehlgeschlagen: ${error.message}`)}};$('[data-close]',d).onclick=()=>{d.close();cloudReady=true}}
function profileSelectMarkup(selected=''){return `<div class="field"><label for="profileName">Profil</label><select id="profileName" name="profileName"><option value="">Profil auswählen …</option>${familyProfiles.map(name=>`<option value="${name}" ${name===selected?'selected':''}>${name}</option>`).join('')}</select></div>`}
async function claimCloudProfile(name){if(!familyProfiles.includes(name))throw Error('Bitte wähle eines der vier Profile.');if(!profileEmailMatches(name,cloudUser?.email))throw Error(`Für ${name} ist ausschließlich ${profileEmails[name]||'die festgelegte E-Mail-Adresse'} zugelassen.`);const {data:profile,error}=await cloudClient.from('fitness_profiles').insert({user_id:cloudUser.id,display_name:name}).select('display_name').single();if(error)throw Error(error.code==='23505'?'Dieses Profil ist bereits vergeben. Bitte wähle ein anderes.':error.message);activeProfileName=profile.display_name;localStorage.setItem(`grevingfit-profile:${cloudUser.id}`,activeProfileName);render();updateCloudButton()}
async function ensureCloudProfile(requestedName=null){const {data:profile,error}=await cloudClient.from('fitness_profiles').select('display_name').eq('user_id',cloudUser.id).maybeSingle();if(error)throw error;if(profile){if(!profileEmailMatches(profile.display_name,cloudUser.email))throw Error(`Dieses Konto passt nicht zum Profil ${profile.display_name}.`);activeProfileName=profile.display_name;localStorage.setItem(`grevingfit-profile:${cloudUser.id}`,activeProfileName);return true}if(requestedName){await claimCloudProfile(requestedName);return true}showProfileClaimModal();return false}
function prepareLocalForUser(userId){const userKey=`${KEY}:${userId}`,saved=localStorage.getItem(userKey),previousOwner=localStorage.getItem(CLOUD_OWNER_KEY);if(saved)data=normalizeData(JSON.parse(saved));else if(previousOwner&&previousOwner!==userId)data=freshData();else data=load();localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(userKey,JSON.stringify(data))}
async function activateCloudUser(user,requestedName=null){cloudUser=user;cloudReady=false;prepareLocalForUser(user.id);updateCloudButton();if(await ensureCloudProfile(requestedName)){cloudVersion=Number(localStorage.getItem(CLOUD_VERSION_KEY))||null;await cloudInitialSync()}}
function showEmptyCloudChoices(){const d=modal(`<h2>Neues GrevingFit-Profil</h2><p>Für ${esc(activeProfileName)} gibt es noch keine Cloud-Sicherung.</p><div class="grid"><button class="button" type="button" data-cloud-empty>Mit Beispiel-Vorlagen starten</button><button class="button secondary" type="button" data-cloud-upload>Aktuelle lokale Daten übernehmen</button></div><p class="tiny muted">Die lokalen Daten könnten von einem anderen Profil stammen. Übernimm sie nur, wenn das beabsichtigt ist.</p>`);$('[data-cloud-empty]',d).onclick=async()=>{data=freshData();localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));localStorage.removeItem(CLOUD_DIRTY_KEY);const row=await cloudWrite(data,null);if(row){cloudReady=true;d.close();render();toast('Neues Profil eingerichtet')}};$('[data-cloud-upload]',d).onclick=async()=>{try{const row=await cloudWrite(data,null);if(row){cloudReady=true;d.close();toast('Lokale Daten ins Profil übernommen')}}catch(error){alert(error.message)}}}
function cloudModal(){if(cloudUser){const d=modal(`<h2>Cloud-Synchronisierung</h2><p>Angemeldet als <strong>${esc(activeProfileName||cloudUser.email||'Konto')}</strong><br><span class="tiny muted">${esc(cloudUser.email||'')}</span></p><div class="grid"><button class="button" type="button" data-cloud-sync>Jetzt synchronisieren</button><button class="button secondary" type="button" data-cloud-signout>Abmelden</button></div><p class="tiny muted" style="margin-top:14px">Änderungen werden automatisch synchronisiert. Jedes Familienprofil hat eine eigene Datenablage.</p>`);$('[data-cloud-sync]',d).onclick=()=>{d.close();cloudInitialSync()};$('[data-cloud-signout]',d).onclick=async()=>{await cloudClient.auth.signOut();cloudUser=null;cloudVersion=null;cloudReady=false;activeProfileName='';data=freshData();localStorage.setItem(KEY,JSON.stringify(data));updateCloudButton();d.close();render();toast('Von der Cloud abgemeldet')};return}const config=storedCloudConfig(),pending=localStorage.getItem('grevingfit-pending-profile')||'',d=modal(`<h2>GrevingFit-Cloud</h2><p>Melde dich an oder erstelle ein persönliches Familienkonto.</p><form id="cloudLoginForm"><div class="field"><label for="cloudEmail">E-Mail</label><input id="cloudEmail" name="email" type="email" required autocomplete="username"></div><div class="field"><label for="cloudPassword">Passwort</label><input id="cloudPassword" name="password" type="password" required autocomplete="current-password"></div>${profileSelectMarkup(pending)}<div class="grid"><button class="button" type="submit">Anmelden</button><button class="button secondary" type="button" data-cloud-signup>Konto erstellen</button></div><p class="tiny muted" id="cloudMessage" style="margin-top:12px"></p></form>`);const form=$('#cloudLoginForm',d),message=$('#cloudMessage',d);form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),profileName=f.get('profileName'),email=f.get('email').trim().toLowerCase();if(!profileEmailMatches(profileName,email)){message.textContent=`Für ${profileName||'das ausgewählte Profil'} ist nur ${profileEmails[profileName]||'die zugehörige E-Mail-Adresse'} zugelassen.`;return}try{createCloudClient(config);const {data:result,error}=await cloudClient.auth.signInWithPassword({email,password:f.get('password')});if(error)throw error;await activateCloudUser(result.user|| (await cloudClient.auth.getUser()).data.user,profileName);if(activeProfileName)d.close()}catch(error){message.textContent=error.message||'Anmeldung fehlgeschlagen.'}};$('[data-cloud-signup]',d).onclick=async()=>{const f=new FormData(form),profileName=f.get('profileName'),email=f.get('email').trim().toLowerCase();if(!profileName){message.textContent='Bitte wähle eines der vier Profile.';return}if(!profileEmailMatches(profileName,email)){message.textContent=`Für ${profileName} ist ausschließlich ${profileEmails[profileName]} zugelassen.`;return}if(!form.reportValidity())return;try{localStorage.setItem('grevingfit-pending-profile',profileName);createCloudClient(config);const {data:result,error}=await cloudClient.auth.signUp({email,password:f.get('password')});if(error)throw error;if(result.session){await activateCloudUser(result.user||result.session.user,profileName);d.close()}else message.textContent='Konto erstellt. Bestätige die E-Mail und melde dich danach mit diesem Profil an.'}catch(error){message.textContent=error.message||'Konto konnte nicht erstellt werden.'}}}
function formatDate(iso,opts={day:'numeric',month:'short',year:'numeric'}){return new Date(iso+'T12:00:00').toLocaleDateString('de-DE',opts)}
function getRoute(){return (location.hash.replace('#','').split('?')[0])||'home'}
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function workouts(){return [...data.history].sort((a,b)=>b.date.localeCompare(a.date))}
function sessionsThisWeek(){const d=new Date(),start=new Date(d);start.setDate(d.getDate()-((d.getDay()+6)%7));start.setHours(0,0,0,0);return data.history.filter(h=>new Date(h.date+'T12:00:00')>=start).length}
function volume(session){return (session.exercises||[]).reduce((sum,e)=>sum+(e.sets||[]).reduce((s,set)=>s+(+set.weight||0)*(+set.reps||0),0),0)}
function render(){const route=getRoute();$$('#appMenu a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));const app=$('#app');if(route==='plan')app.innerHTML=renderPlan();else if(route==='catalog')app.innerHTML=renderCatalog();else if(route==='music')app.innerHTML=renderMusic();else if(route==='history')app.innerHTML=renderHistory();else if(route==='stats')app.innerHTML=renderStats();else if(route==='session')app.innerHTML=renderSession();else app.innerHTML=renderHome();bind()}
function renderHome(){const sessions=workouts(),last=sessions[0],name=activeProfileName?` · ${esc(activeProfileName)}`:'';return `<div class="eyebrow">${new Date().toLocaleDateString('de-DE',{weekday:'long',day:'numeric',month:'long'})}${name}</div><div class="heading-row"><div><h1 class="hero-title">Zeit für dich.</h1><p class="subtitle">Ein guter Satz nach dem anderen.</p></div></div><div class="grid stats-grid"><div class="metric"><div class="metric-label">Einheiten diese Woche</div><div class="metric-value">${sessionsThisWeek()}</div><div class="metric-note">Konstanz zählt</div></div><div class="metric"><div class="metric-label">Trainings gesamt</div><div class="metric-value">${data.history.length}</div><div class="metric-note">Jede Einheit zählt</div></div><div class="metric"><div class="metric-label">Zuletzt trainiert</div><div class="metric-value" style="font-size:20px">${last?formatDate(last.date,{day:'numeric',month:'short'}):'–'}</div><div class="metric-note">${last?esc(last.name):'Dein Startpunkt'}</div></div></div><section class="workout-banner"><div><div class="eyebrow">DEIN TRAINING</div><h2>Heute trainieren?</h2><p>Stelle spontan eine Einheit zusammen oder starte mit einer Vorlage.</p></div><button class="button" data-action="free-session">Freies Training starten →</button></section><section class="card"><div class="card-head"><h2>Deine Vorlagen</h2><a href="#plan" class="tiny muted">Alle Vorlagen →</a></div>${data.plan.length?data.plan.slice(0,3).map(w=>`<div class="exercise-row"><div class="exercise-number">▤</div><div class="exercise-info"><strong>${esc(w.name)}</strong><span>${w.exercises.length} Übungen</span></div><button class="button small" data-start="${w.id}">Starten</button></div>`).join(''):`<div class="empty">Noch keine Vorlagen. Du kannst eine freie Einheit erstellen und als Vorlage speichern.</div>`}</section><section class="card"><div class="card-head"><h2>Letzte Einheit</h2><a href="#history" class="tiny muted">Verlauf ansehen →</a></div>${last?historyRow(last):`<div class="empty"><div class="empty-icon">↗</div><strong>Dein Fortschritt beginnt hier</strong><p>Protokolliere deine erste Einheit, um deinen Verlauf zu sehen.</p></div>`}</section>`}
function exerciseRow(e,i){return `<div class="exercise-row"><div class="exercise-number">${String(i+1).padStart(2,'0')}</div><div class="exercise-info"><strong>${esc(e.name)}</strong><span>${e.sets} Sätze · ${esc(e.reps)} Wdh</span></div><div class="exercise-meta">${bestFor(e.name)||'–'}</div></div>`}
function bestFor(name){for(const s of workouts())for(const e of s.exercises||[])if(e.name===name){const best=Math.max(0,...(e.sets||[]).map(x=>+x.weight||0));if(best)return `${best} kg`; }return ''}
function renderPlan(){return `<div class="eyebrow">TRAININGSABLAUF</div><div class="heading-row"><div><h1>Einheiten & Vorlagen</h1><p class="subtitle">Keine Wochenbindung – trainiere, wann du möchtest.</p></div><button class="button" data-action="new-workout">＋ Vorlage erstellen</button></div><section class="workout-banner"><div><div class="eyebrow">FLEXIBEL TRAINIEREN</div><h2>Spontan zusammenstellen</h2><p>Übungen für eine einzelne Einheit auswählen und direkt protokollieren.</p></div><button class="button" data-action="free-session">Freies Training →</button></section><section class="card"><div class="card-head"><h2>${data.plan.length} Vorlagen</h2><a href="#catalog" class="tiny muted">Übungskatalog →</a></div>${data.plan.length?data.plan.map(w=>`<article class="template-card"><div class="card-head"><div><h2>${esc(w.name)}</h2><span class="tiny muted">${w.exercises.length} Übungen</span></div><div class="exercise-actions"><button class="icon-action" title="Vorlage bearbeiten" data-edit-workout="${esc(w.id)}">✎</button><button class="icon-action" title="Vorlage löschen" data-delete-workout="${esc(w.id)}">×</button></div></div>${w.exercises.map((e,i)=>planExerciseRow(e,i,w.id)).join('')}<div class="split template-actions"><button class="button secondary small" data-add-exercise="${esc(w.id)}">＋ Übung</button><button class="button small" data-start="${esc(w.id)}">Einheit starten →</button></div></article>`).join(''):`<div class="empty"><strong>Noch keine Vorlagen</strong><p>Erstelle eine Vorlage oder speichere ein freies Training als Vorlage.</p></div>`}</section>`}
function planExerciseRow(e,i,id){return `<div class="exercise-row"><div class="exercise-number">${String(i+1).padStart(2,'0')}</div><div class="exercise-info"><strong>${esc(e.name)}</strong><span>${e.sets} Sätze · ${esc(e.reps)} Wdh</span></div><div class="exercise-actions"><button class="icon-action" title="Übung bearbeiten" data-edit-exercise="${id}:${i}">✎</button><button class="icon-action" title="Übung entfernen" data-delete-exercise="${id}:${i}">×</button></div></div>`}
function catalogItem(name){return (data.catalog||[]).find(item=>item.name.toLocaleLowerCase()===name.toLocaleLowerCase())}
function lastExerciseUse(name){for(const session of workouts()){const exercise=(session.exercises||[]).find(item=>item.name===name);if(exercise)return {session,exercise}}return null}
function lastValueText(name){const last=lastExerciseUse(name);if(!last)return 'Noch nicht verwendet';const sets=last.exercise.sets||[],weight=Math.max(0,...sets.map(set=>+set.weight||0)),reps=sets.map(set=>+set.reps||0).filter(Boolean);return `${sets.length||'–'} Sätze${weight?` · bis ${weight} kg`:''}${reps.length?` · zuletzt ${reps.join('/')} Wdh`:''} · ${formatDate(last.session.date,{day:'numeric',month:'short'})}`}
function renderCatalog(){const groups=muscleGroups.filter(group=>(data.catalog||[]).some(item=>(item.group||'Sonstige')===group));return `<div class="eyebrow">DEIN ÜBUNGSVORRAT</div><div class="heading-row"><div><h1>Übungskatalog</h1><p class="subtitle">Übungen und die zuletzt verwendeten Satzwerte.</p></div></div><section class="card"><div class="card-head"><h2>${(data.catalog||[]).length} Übungen</h2><a href="#plan" class="tiny muted">Zu Einheiten →</a></div><p class="tiny muted">Satzwerte werden aus der letzten Verwendung übernommen.</p></section>${groups.map(group=>`<section class="card"><div class="card-head"><h2>${esc(group)}</h2></div>${data.catalog.filter(item=>(item.group||'Sonstige')===group).map(item=>`<div class="exercise-row"><div class="exercise-number">↗</div><div class="exercise-info"><strong>${esc(item.name)}</strong><span>${item.sets} Sätze · ${esc(item.reps)} Wdh</span><span class="tiny" style="color:var(--lime)">Zuletzt: ${esc(lastValueText(item.name))}</span></div><div class="exercise-actions"><button class="icon-action" title="Übung bearbeiten" data-catalog-edit="${esc(item.name)}">✎</button><button class="icon-action" title="Übung löschen" data-catalog-delete="${esc(item.name)}">×</button></div></div>`).join('')}</section>`).join('')}<section class="card"><div class="card-head"><h2>Eigene Übung hinzufügen</h2></div><p class="muted tiny">Wähle eine Muskelgruppe aus der festen Liste.</p><button class="button secondary small" data-action="catalog-add">＋ Neue Katalogübung</button></section>`}
function spotifyTarget(input){const value=(input||'').trim(),url=value.match(/open\.spotify\.com\/(playlist|track|album|artist|show|episode)\/([A-Za-z0-9]+)/),uri=value.match(/^spotify:(playlist|track|album|artist|show|episode):([A-Za-z0-9]+)$/);if(url)return {type:url[1],id:url[2],link:`https://open.spotify.com/${url[1]}/${url[2]}`,uri:`spotify:${url[1]}:${url[2]}`};if(uri)return {type:uri[1],id:uri[2],link:`https://open.spotify.com/${uri[1]}/${uri[2]}`,uri:`spotify:${uri[1]}:${uri[2]}`};return null}

function setSpotifyStatus(text){spotifyPlaybackStatus=text;const el=$('#spotifyStatus');if(el)el.textContent=text}
function base64url(buffer){return btoa(String.fromCharCode(...new Uint8Array(buffer))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function spotifyRedirectUri(){return location.origin+location.pathname}
async function spotifyConnect(){if(spotifyProfileToken()){await initializeSpotifyPlayer();return}const clientId=$('#spotifyClientId')?.value.trim()||localStorage.getItem(SPOTIFY_CLIENT_KEY)||'';if(!clientId){alert('Trage zuerst deine Spotify Client-ID ein.');return}localStorage.setItem(SPOTIFY_CLIENT_KEY,clientId);const verifier=base64url(crypto.getRandomValues(new Uint8Array(64))),challenge=base64url(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))),state=base64url(crypto.getRandomValues(new Uint8Array(24)));sessionStorage.setItem(SPOTIFY_VERIFIER_KEY,verifier);sessionStorage.setItem(SPOTIFY_STATE_KEY,state);const url=new URL('https://accounts.spotify.com/authorize');url.search=new URLSearchParams({client_id:clientId,response_type:'code',redirect_uri:spotifyRedirectUri(),scope:'streaming user-read-email user-read-private user-read-playback-state user-modify-playback-state',code_challenge_method:'S256',code_challenge:challenge,state}).toString();location.assign(url)}
async function exchangeSpotifyCode(code){const verifier=sessionStorage.getItem(SPOTIFY_VERIFIER_KEY),state=sessionStorage.getItem(SPOTIFY_STATE_KEY),params=new URLSearchParams(location.search);if(!verifier||!state||params.get('state')!==state)throw Error('Spotify-Anmeldung fehlgeschlagen: ungültige Sitzung.');const body=new URLSearchParams({client_id:localStorage.getItem(SPOTIFY_CLIENT_KEY)||'',grant_type:'authorization_code',code,redirect_uri:spotifyRedirectUri(),code_verifier:verifier});const response=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const result=await response.json();if(!response.ok)throw Error(result.error_description||'Spotify-Token konnte nicht abgerufen werden.');spotifyAccessToken=result.access_token;spotifyTokenExpires=Date.now()+result.expires_in*1000;if(result.refresh_token)localStorage.setItem(spotifyRefreshKey(),result.refresh_token);sessionStorage.removeItem(SPOTIFY_VERIFIER_KEY);sessionStorage.removeItem(SPOTIFY_STATE_KEY);history.replaceState({},'',location.pathname+location.hash);setSpotifyStatus('Spotify-Konto verbunden');ensureSpotifySdk()}
async function finishSpotifyCallback(){const params=new URLSearchParams(location.search);if(params.get('error')){history.replaceState({},'',location.pathname+location.hash);toast('Spotify-Anmeldung wurde abgebrochen');return}if(params.get('code')){try{await exchangeSpotifyCode(params.get('code'));await initializeSpotifyPlayer()}catch(error){toast(error.message||'Spotify-Anmeldung fehlgeschlagen')}}}
async function spotifyToken(){if(spotifyAccessToken&&spotifyTokenExpires>Date.now()+60000)return spotifyAccessToken;const refresh=spotifyProfileToken(),clientId=localStorage.getItem(SPOTIFY_CLIENT_KEY);if(!refresh||!clientId)throw Error('Verbinde zuerst dein Spotify Premium-Konto.');const response=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:clientId,grant_type:'refresh_token',refresh_token:refresh})}),result=await response.json();if(!response.ok)throw Error(result.error_description||'Spotify-Anmeldung abgelaufen. Bitte erneut verbinden.');spotifyAccessToken=result.access_token;spotifyTokenExpires=Date.now()+(result.expires_in||3600)*1000;if(result.refresh_token)localStorage.setItem(spotifyRefreshKey(),result.refresh_token);return spotifyAccessToken}
function ensureSpotifySdk(){if(window.Spotify?.Player){initializeSpotifyPlayer();return}if(spotifySdkLoaded)return;spotifySdkLoaded=true;window.onSpotifyWebPlaybackSDKReady=()=>initializeSpotifyPlayer();const script=document.createElement('script');script.src='https://sdk.scdn.co/spotify-player.js';script.async=true;script.onerror=()=>setSpotifyStatus('Spotify-Player konnte nicht geladen werden');document.head.append(script)}
async function initializeSpotifyPlayer(){if(spotifyPlayer)return;try{await spotifyToken();if(!window.Spotify?.Player){ensureSpotifySdk();return}spotifyPlayer=new Spotify.Player({name:'GrevingFit',volume:.7,getOAuthToken:callback=>spotifyToken().then(callback).catch(error=>setSpotifyStatus(error.message))});spotifyPlayer.addListener('ready',({device_id})=>{spotifyDeviceId=device_id;setSpotifyStatus('Player bereit – Wiedergabe über GrevingFit')});spotifyPlayer.addListener('not_ready',()=>{spotifyDeviceId='';setSpotifyStatus('Player nicht erreichbar')});spotifyPlayer.addListener('initialization_error',({message})=>setSpotifyStatus(`Player-Fehler: ${message}`));spotifyPlayer.addListener('authentication_error',({message})=>setSpotifyStatus(`Spotify-Anmeldung fehlgeschlagen: ${message}`));spotifyPlayer.addListener('account_error',({message})=>setSpotifyStatus(`Spotify Premium benötigt: ${message}`));spotifyPlayer.addListener('playback_error',({message})=>setSpotifyStatus(`Wiedergabefehler: ${message}`));spotifyPlayer.addListener('player_state_changed',state=>{if(state)setSpotifyStatus(`Wiedergabe: ${state.track_window.current_track.name}`)});await spotifyPlayer.connect();setSpotifyStatus('Verbinde Spotify-Player …')}catch(error){setSpotifyStatus(error.message||'Spotify konnte nicht verbunden werden')}}
async function playSpotifyTarget(){const target=spotifyTarget(data.musicUrl);if(!target){alert('Speichere zuerst einen Spotify-Track, ein Album oder eine Playlist.');return}try{await initializeSpotifyPlayer();if(!spotifyPlayer||!spotifyDeviceId){setSpotifyStatus('Player wird verbunden – tippe gleich noch einmal auf Wiedergabe.');return}await spotifyPlayer.activateElement();const token=await spotifyToken(),body=target.type==='track'?{uris:[target.uri]}:{context_uri:target.uri},response=await fetch(`https://api.spotify.com/v1/me/player/play?device_id=${encodeURIComponent(spotifyDeviceId)}`,{method:'PUT',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok){const error=await response.json().catch(()=>({}));throw Error(error.error?.message||`Spotify Player Fehler (${response.status})`)}setSpotifyStatus('Wiedergabe gestartet')}catch(error){setSpotifyStatus(error.message||'Spotify-Wiedergabe fehlgeschlagen')}}
function renderMusic(){const target=spotifyTarget(data.musicUrl),clientId=localStorage.getItem(SPOTIFY_CLIENT_KEY)||'',connected=Boolean(spotifyProfileToken());return `<div class="eyebrow">DEIN TRAININGSSOUND</div><div class="heading-row"><div><h1>Musik</h1><p class="subtitle">Spotify Premium direkt im GrevingFit-Player hören.</p></div></div><section class="card"><div class="card-head"><h2>Spotify Premium Player</h2><span class="pill">Spotify</span></div><p class="muted tiny">Der Web Playback SDK streamt vollständige Tracks über dein Premium-Konto. Ein Spotify-Developer-Client ist erforderlich.</p><div class="field"><label for="spotifyClientId">Spotify Client ID</label><input id="spotifyClientId" value="${esc(clientId)}" placeholder="Client ID aus developer.spotify.com" autocomplete="off"></div><div class="split"><button class="button" type="button" data-spotify-connect>${connected?'Player verbinden':'Mit Spotify Premium verbinden'}</button>${connected?`<button class="button secondary" type="button" data-spotify-play>▶ Wiedergabe</button>`:''}</div><p class="tiny muted" id="spotifyStatus" role="status">${esc(spotifyPlaybackStatus)}</p>${connected?`<div class="spotify-controls"><button class="button secondary small" data-spotify-previous aria-label="Vorheriger Titel">⏮</button><button class="button secondary small" data-spotify-toggle aria-label="Wiedergabe pausieren oder fortsetzen">⏯</button><button class="button secondary small" data-spotify-next aria-label="Nächster Titel">⏭</button></div>`:''}<p class="tiny muted">Spotify Developer Dashboard: App mit Web Playback SDK anlegen und als Redirect URI eintragen: <code>${esc(spotifyRedirectUri())}</code>. Client ID dort kopieren. Spotify verlangt für den Web Playback SDK ein Premium-Konto.</p></section><section class="card"><div class="card-head"><h2>Track oder Playlist auswählen</h2></div><p class="muted tiny">Speichere den Spotify-Link; der Premium-Player startet die vollständige Wiedergabe auf diesem Gerät.</p><form id="spotifyForm"><div class="field"><label for="spotifyUrl">Spotify-Link</label><input id="spotifyUrl" name="url" type="url" value="${esc(data.musicUrl||'')}" placeholder="https://open.spotify.com/playlist/…"></div><div class="split"><button class="button secondary" type="submit">${target?'Spotify-Link aktualisieren':'Spotify-Link speichern'}</button>${target?`<a class="button ghost" href="${target.link}" target="_blank" rel="noopener">In Spotify öffnen ↗</a>`:''}</div></form></section>${target?`<section class="card"><h2>Ausgewählter Inhalt</h2><p class="muted tiny">${esc(target.type)} · ${esc(target.id)}</p><button class="button" data-spotify-play>▶ Vollständig im GrevingFit-Player abspielen</button></section>`:''}<p class="tiny muted">Falls Wiedergabe nicht startet: Spotify App im Developer Dashboard als Testnutzer freigeben, Premium prüfen und GrevingFit als Redirect URI eintragen.</p>`}
function renderHistory(){let items=workouts();if(historyFilter!=='Alle')items=items.filter(s=>s.name===historyFilter);return `<div class="eyebrow">DEIN WEG</div><div class="heading-row"><div><h1>Trainingsverlauf</h1><p class="subtitle">Jede Wiederholung bringt dich weiter.</p></div><button class="button secondary" data-action="log-manual">＋ Einheit eintragen</button></div><div class="filter-row"><button class="filter-chip ${historyFilter==='Alle'?'active':''}" data-filter="Alle">Alle</button>${[...new Set(data.history.map(h=>h.name))].map(n=>`<button class="filter-chip ${historyFilter===n?'active':''}" data-filter="${esc(n)}">${esc(n)}</button>`).join('')}</div><section class="card">${items.length?items.map(historyRow).join(''):`<div class="empty"><div class="empty-icon">◷</div><strong>Noch kein Verlauf</strong><p>Starte ein Training und speichere deine Sätze. Hier entsteht deine Trainingshistorie.</p><a class="button" href="#home">Zum Training</a></div>`}</section>`}
function historyRow(s){let count=(s.exercises||[]).reduce((n,e)=>n+(e.sets||[]).length,0);return `<div class="history-item"><div class="history-date"><b>${new Date(s.date+'T12:00:00').getDate()}</b>${new Date(s.date+'T12:00:00').toLocaleDateString('de-DE',{month:'short'})}</div><div class="history-desc"><strong>${esc(s.name)}</strong><span>${(s.exercises||[]).length} Übungen · ${count} Arbeitssätze${volume(s)?` · ${Math.round(volume(s)).toLocaleString('de-DE')} kg Volumen`:''}</span></div><span class="pill">${formatDate(s.date,{weekday:'short'})}</span><button class="icon-action" title="Einheit löschen" data-delete-session="${s.id}">×</button></div>`}
function renderStats(){let sessions=workouts(),names=[...new Set(sessions.flatMap(s=>(s.exercises||[]).map(e=>e.name)))];let selected=new URLSearchParams(location.hash.split('?')[1]||'').get('exercise')||names[0]||'';let points=[];sessions.slice().reverse().forEach(s=>(s.exercises||[]).forEach(e=>{if(e.name===selected){const max=Math.max(0,...e.sets.map(set=>+set.weight||0));if(max)points.push({date:s.date,weight:max,reps:Math.max(0,...e.sets.map(set=>+set.reps||0))})}}));let chart=chartSvg(points);let totalVolume=sessions.reduce((n,s)=>n+volume(s),0);return `<div class="eyebrow">KLEINE SCHRITTE, STARKE ERGEBNISSE</div><div class="heading-row"><div><h1>Deine Auswertung</h1><p class="subtitle">Sieh, was du dir aufgebaut hast.</p></div></div><div class="chart-summary"><div class="metric"><div class="metric-label">Trainings gesamt</div><div class="metric-value">${sessions.length}</div></div><div class="metric"><div class="metric-label">Gesamtvolumen</div><div class="metric-value">${totalVolume?Math.round(totalVolume).toLocaleString('de-DE'):'0'} <small style="font-size:12px">kg</small></div></div></div><section class="card" style="margin-top:16px"><div class="card-head"><div><h2>Kraftverlauf</h2><div class="tiny muted" style="margin-top:5px">Dein schwerster Arbeitssatz je Einheit</div></div></div>${names.length?`<div class="filter-row">${names.map(n=>`<button class="filter-chip ${selected===n?'active':''}" data-exercise="${encodeURIComponent(n)}">${esc(n)}</button>`).join('')}</div>${chart}<div class="split" style="justify-content:space-between"><span class="tiny muted">${points.length?`${points.length} Einheiten dokumentiert`:'Noch keine Gewichte für diese Übung'}</span>${points.length?`<span class="pill">Bestwert ${Math.max(...points.map(p=>p.weight))} kg</span>`:''}</div>`:`<div class="empty"><div class="empty-icon">↗</div><strong>Deine Auswertung wartet auf Daten</strong><p>Trage bei deinen Übungen Gewichte und Wiederholungen ein, dann siehst du hier deine Entwicklung.</p></div>`}</section><section class="card"><div class="card-head"><h2>Bewegung im Überblick</h2></div>${sessions.length?`<div class="metric-label">Trainingshäufigkeit · letzte 8 Wochen</div><div class="chart-wrap">${frequencyChart(sessions)}</div>`:`<div class="empty">Starte mit deiner ersten Einheit und baue deine Serie auf.</div>`}</section>`}
function chartSvg(points){if(!points.length)return `<div class="empty">Protokolliere dein erstes Gewicht für diese Übung.</div>`;let values=points.map(p=>p.weight),min=Math.min(...values),max=Math.max(...values);if(min===max){min=Math.max(0,min-5);max+=5}let w=600,h=190,pad={l:34,r:12,t:16,b:28},x=i=>pad.l+(points.length===1?(w-pad.l-pad.r)/2:i*(w-pad.l-pad.r)/(points.length-1)),y=v=>pad.t+(max-v)*(h-pad.t-pad.b)/(max-min);let coords=points.map((p,i)=>`${x(i)},${y(p.weight)}`).join(' ');return `<div class="chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Gewichtsverlauf für ${esc(points[0]&&selectedName())}"><line class="chart-grid" x1="${pad.l}" y1="${pad.t}" x2="${w-pad.r}" y2="${pad.t}"/><line class="chart-grid" x1="${pad.l}" y1="${h/2}" x2="${w-pad.r}" y2="${h/2}"/><line class="chart-grid" x1="${pad.l}" y1="${h-pad.b}" x2="${w-pad.r}" y2="${h-pad.b}"/><text class="chart-label" x="0" y="${pad.t+4}">${max} kg</text><text class="chart-label" x="0" y="${h-pad.b+4}">${min} kg</text><polyline class="chart-line" points="${coords}"/>${points.map((p,i)=>`<circle class="chart-dot" cx="${x(i)}" cy="${y(p.weight)}" r="5"><title>${formatDate(p.date)} · ${p.weight} kg</title></circle>`).join('')}<text class="chart-label" x="${pad.l}" y="${h-2}">${formatDate(points[0].date,{day:'numeric',month:'short'})}</text><text class="chart-label" text-anchor="end" x="${w-pad.r}" y="${h-2}">${formatDate(points.at(-1).date,{day:'numeric',month:'short'})}</text></svg></div>`}
function selectedName(){return new URLSearchParams(location.hash.split('?')[1]||'').get('exercise')||''}
function frequencyChart(sessions){let count=Array(8).fill(0),now=new Date();sessions.forEach(s=>{let diff=Math.floor((now-new Date(s.date+'T12:00:00'))/(7*86400000));if(diff<8&&diff>=0)count[7-diff]++});let w=600,h=180,p=12,max=Math.max(3,...count),bar=(w-2*p)/8;return `<svg viewBox="0 0 ${w} ${h}" aria-label="Einheiten der letzten acht Wochen">${count.map((c,i)=>`<rect x="${p+i*bar+bar*.18}" y="${h-28-Math.max(4,c/max*125)}" width="${bar*.64}" height="${Math.max(4,c/max*125)}" rx="6" fill="${c?'#c6f36b':'#31372f'}"/><text class="chart-label" text-anchor="middle" x="${p+i*bar+bar/2}" y="${h-8}">${i===7?'Jetzt':`${7-i}W`}</text><text class="chart-label" text-anchor="middle" x="${p+i*bar+bar/2}" y="${h-34-Math.max(4,c/max*125)}">${c}</text>`).join('')}</svg>`}
function renderSession(){const params=new URLSearchParams(location.hash.split('?')[1]||''),isFree=params.get('free')==='1',id=params.get('id');if(isFree&&!sessionDraft)sessionDraft={id:crypto.randomUUID(),name:'Spontanes Training',exercises:[]};const w=isFree?sessionDraft:data.plan.find(x=>x.id===id);if(!w){location.hash='#plan';return ''}return `<div class="eyebrow">${isFree?'FREIES TRAINING':'VORLAGEN-TRAINING'} · ${new Date().toLocaleDateString('de-DE',{day:'numeric',month:'long'})}</div><div class="heading-row"><div><h1>${esc(w.name)}</h1><p class="subtitle">Die Einheit wird beim Speichern mit dem heutigen Datum protokolliert.</p></div>${isFree?'<button class="button secondary small" type="button" data-action="free-add-exercise">＋ Übung</button>':''}</div><form id="sessionForm" data-workout="${esc(w.id)}" data-free="${isFree}">${w.exercises.length?w.exercises.map((e,i)=>{const previous=lastExerciseUse(e.name)?.exercise.sets||[];return `<section class="card session-exercise"><h3><span class="exercise-number" style="display:inline-grid;vertical-align:middle;margin-right:7px">${i+1}</span>${esc(e.name)} <span class="muted tiny">· Ziel ${esc(e.reps)}</span></h3>${Array.from({length:+e.sets||1},(_,j)=>{const prior=previous.find(set=>set.setNo===j+1)||previous[j];return `<div class="set-row"><span>S${j+1}</span><input name="weight-${i}-${j}" type="number" inputmode="decimal" step="0.5" min="0" value="${esc(prior?.weight||'')}" placeholder="kg" aria-label="${esc(e.name)} Satz ${j+1} Gewicht"><input name="reps-${i}-${j}" type="number" inputmode="numeric" step="1" min="0" value="${esc(prior?.reps||'')}" placeholder="Wdh" aria-label="${esc(e.name)} Satz ${j+1} Wiederholungen"><em>kg · Wdh</em></div>`}).join('')}<div class="field" style="margin:12px 0 0"><input name="note-${i}" placeholder="Notiz (optional)" aria-label="Notiz für ${esc(e.name)}"></div></section>`}).join(''):`<section class="card empty"><strong>Noch keine Übungen</strong><p>Füge eine Übung aus dem Katalog hinzu.</p><button class="button secondary" type="button" data-action="free-add-exercise">＋ Übung hinzufügen</button></section>`}<div class="field"><label for="sessionNote">Notiz zur Einheit</label><textarea name="note" id="sessionNote" rows="2" placeholder="Wie lief's heute?"></textarea></div>${isFree?`<label class="save-template-option"><input type="checkbox" name="saveTemplate"> Als Vorlage für später speichern</label><div class="field template-name-field" hidden><label for="templateName">Name der Vorlage</label><input id="templateName" name="templateName" value="${esc(w.name)}"></div>`:''}<div class="split session-submit"><button class="button secondary" type="button" data-action="cancel-session">Abbrechen</button><button class="button" type="submit">Training speichern ✓</button></div></form>`}
function bind(){$$('[data-start]').forEach(el=>el.onclick=()=>{sessionDraft=null;location.hash=`#session?id=${encodeURIComponent(el.dataset.start)}`});$$('[data-action="free-session"]').forEach(el=>el.onclick=startFreeSession);$$('[data-action="free-add-exercise"]').forEach(el=>el.onclick=freeExerciseDialog);$$('[data-action="new-workout"]').forEach(el=>el.onclick=()=>workoutDialog());$$('[data-edit-workout]').forEach(el=>el.onclick=()=>workoutDialog(data.plan.find(w=>w.id===el.dataset.editWorkout)));$$('[data-delete-workout]').forEach(el=>el.onclick=()=>{if(confirm('Diese Vorlage löschen?')){data.plan=data.plan.filter(w=>w.id!==el.dataset.deleteWorkout);save();render()}});$$('[data-add-exercise]').forEach(el=>el.onclick=()=>exerciseDialog(el.dataset.addExercise));$$('[data-edit-exercise]').forEach(el=>el.onclick=()=>{const [id,index]=el.dataset.editExercise.split(':');exerciseDialog(id,+index)});$$('[data-delete-exercise]').forEach(el=>el.onclick=()=>{const [id,index]=el.dataset.deleteExercise.split(':');const w=data.plan.find(x=>x.id===id);if(w&&confirm(`„${w.exercises[index]?.name}“ aus der Vorlage entfernen?`)){w.exercises.splice(+index,1);save();render()}});$$('[data-action="catalog-add"]').forEach(el=>el.onclick=()=>catalogEditDialog());$$('[data-catalog-edit]').forEach(el=>el.onclick=()=>catalogEditDialog(el.dataset.catalogEdit));$$('[data-catalog-delete]').forEach(el=>el.onclick=()=>{const name=el.dataset.catalogDelete;if(confirm(`„${name}“ aus dem Übungskatalog entfernen?`)){data.catalog=data.catalog.filter(item=>item.name!==name);save();render()}});$$('[data-filter]').forEach(el=>el.onclick=()=>{historyFilter=el.dataset.filter;render()});$$('[data-exercise]').forEach(el=>el.onclick=()=>{location.hash=`#stats?exercise=${el.dataset.exercise}`});$$('[data-delete-session]').forEach(el=>el.onclick=()=>{if(confirm('Diese Trainingseinheit aus dem Verlauf löschen?')){data.history=data.history.filter(s=>s.id!==el.dataset.deleteSession);save();render()}});$$('[data-action="log-manual"]').forEach(el=>el.onclick=manualDialog);const form=$('#sessionForm');if(form){form.onsubmit=saveSession;const checkbox=$('[name="saveTemplate"]',form);if(checkbox)checkbox.onchange=()=>$('.template-name-field',form).hidden=!checkbox.checked}const spotify=$('#spotifyForm');if(spotify)spotify.onsubmit=e=>{e.preventDefault();const raw=new FormData(e.currentTarget).get('url').trim(),target=spotifyTarget(raw);if(!target){alert('Bitte füge einen gültigen Spotify-Link oder eine Spotify-URI ein.');return}data.musicUrl=target.link;save();render();toast('Spotify-Link gespeichert')};$$('[data-spotify-connect]').forEach(el=>el.onclick=spotifyConnect);$$('[data-spotify-play]').forEach(el=>el.onclick=playSpotifyTarget);$$('[data-spotify-toggle]').forEach(el=>el.onclick=()=>spotifyPlayer?.togglePlay());$$('[data-spotify-next]').forEach(el=>el.onclick=()=>spotifyPlayer?.nextTrack());$$('[data-spotify-previous]').forEach(el=>el.onclick=()=>spotifyPlayer?.previousTrack());const clientInput=$('#spotifyClientId');if(clientInput)clientInput.onchange=()=>localStorage.setItem(SPOTIFY_CLIENT_KEY,clientInput.value.trim());$$('[data-action="cancel-session"]').forEach(el=>el.onclick=()=>{sessionDraft=null;location.hash='#home'})}
function modal(content){const d=$('#modal');d.className='modal';d.innerHTML=content;d.showModal();d.onclick=e=>{if(e.target===d)d.close()};return d}
function workoutDialog(w){const d=modal(`<h2>${w?'Vorlage bearbeiten':'Neue Vorlage'}</h2><p>Lege eine Einheit an, die du bei Bedarf starten und anpassen kannst.</p><form id="workoutForm"><div class="field"><label>Name der Vorlage</label><input name="name" required maxlength="60" value="${esc(w?.name||'')}" placeholder="z. B. Oberkörper"></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">Speichern</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();$('#workoutForm',d).onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(w)w.name=name;else data.plan.push({id:crypto.randomUUID(),name,exercises:[]});save();d.close();render();toast('Vorlage gespeichert')}}
function exerciseDialog(id,index=null){const w=data.plan.find(x=>x.id===id),exercise=index===null?null:w?.exercises[index];if(!w)return;const initial=exercise||{name:'',sets:3,reps:'8–12'};const options=(data.catalog||[]).map(item=>`<option value="${esc(item.name)}" ${initial.name===item.name?'selected':''}>${esc(item.name)} · ${esc(item.group||'Sonstige')}</option>`).join('');const d=modal(`<h2>${exercise?'Übung bearbeiten':'Aus Katalog hinzufügen'}</h2><p>${esc(w.name)} · letzte Satzwerte werden vorgeschlagen.</p><form id="exerciseForm"><div class="field"><label>Übung aus dem Katalog</label><select name="catalogChoice"><option value="">Übung wählen …</option>${options}<option value="__custom">Eigene Übung …</option></select></div><div class="field"><label>Übungsname</label><input name="name" required maxlength="70" value="${esc(initial.name)}" placeholder="z. B. Bankdrücken"></div><div class="form-grid"><div class="field"><label>Sätze</label><input name="sets" type="number" min="1" max="20" value="${initial.sets}"></div><div class="field"><label>Wiederholungen</label><input name="reps" value="${esc(initial.reps)}" required></div></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">${exercise?'Speichern':'Zur Vorlage hinzufügen'}</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();const form=$('#exerciseForm',d),choice=$('[name="catalogChoice"]',form);choice.onchange=()=>{const item=catalogItem(choice.value);if(item){$('[name="name"]',form).value=item.name;$('[name="sets"]',form).value=item.sets;$('[name="reps"]',form).value=item.reps}else if(choice.value==='__custom')$('[name="name"]',form).focus()};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),updated={name:f.get('name').trim(),sets:+f.get('sets')||3,reps:f.get('reps').trim()};if(index===null)w.exercises.push(updated);else w.exercises[index]=updated;if(!catalogItem(updated.name))data.catalog.push({name:updated.name,group:'Sonstige',sets:updated.sets,reps:updated.reps});save();d.close();render();toast(exercise?'Übung aktualisiert':'Übung hinzugefügt')}}
function catalogEditDialog(name=null){const item=name?catalogItem(name):null;const groupOptions=muscleGroups.map(group=>`<option value="${group}" ${(item?.group||'Sonstige')===group?'selected':''}>${group}</option>`).join('');const d=modal(`<h2>${item?'Katalogübung bearbeiten':'Katalogübung erstellen'}</h2><p>Die letzten Satzwerte werden nach jeder Einheit aktualisiert.</p><form id="catalogForm"><div class="field"><label>Übungsname</label><input name="name" required maxlength="70" value="${esc(item?.name||'')}" placeholder="z. B. Brustpresse"></div><div class="field"><label>Muskelgruppe</label><select name="group" required>${groupOptions}</select></div><div class="form-grid"><div class="field"><label>Sätze</label><input name="sets" type="number" min="1" max="20" value="${item?.sets||3}"></div><div class="field"><label>Wiederholungen</label><input name="reps" required value="${esc(item?.reps||'8–12')}"></div></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">${item?'Speichern':'Im Katalog ablegen'}</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();$('#catalogForm',d).onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),updated={name:f.get('name').trim(),group:muscleGroups.includes(f.get('group'))?f.get('group'):'Sonstige',sets:+f.get('sets')||3,reps:f.get('reps').trim()};if(item){const i=data.catalog.indexOf(item);data.catalog[i]=updated}else if(catalogItem(updated.name)){alert('Diese Übung ist bereits im Katalog.');return}else data.catalog.push(updated);save();d.close();render();toast(item?'Katalog aktualisiert':'Übung im Katalog gespeichert')}}
function startFreeSession(){sessionDraft={id:crypto.randomUUID(),name:'Spontanes Training',exercises:[]};location.hash='#session?free=1'}
function freeExerciseDialog(){if(!sessionDraft)startFreeSession();const options=(data.catalog||[]).map(item=>`<option value="${esc(item.name)}">${esc(item.name)} · ${esc(item.group)}</option>`).join('');const d=modal(`<h2>Übung hinzufügen</h2><p>Wähle eine Katalogübung oder gib eine eigene Übung ein.</p><form id="freeExerciseForm"><div class="field"><label>Aus dem Katalog</label><select name="choice"><option value="">Übung wählen …</option>${options}<option value="__custom">Eigene Übung …</option></select></div><div class="field"><label>Übungsname</label><input name="name" required placeholder="z. B. Bankdrücken"></div><div class="form-grid"><div class="field"><label>Sätze</label><input name="sets" type="number" min="1" max="20" value="3"></div><div class="field"><label>Wiederholungen</label><input name="reps" required value="8–12"></div></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">Hinzufügen</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();const form=$('#freeExerciseForm',d);$('[name="choice"]',form).onchange=()=>{const item=catalogItem($('[name="choice"]',form).value);if(item){$('[name="name"]',form).value=item.name;$('[name="sets"]',form).value=item.sets;$('[name="reps"]',form).value=item.reps}else if($('[name="choice"]',form).value==='__custom')$('[name="name"]',form).focus()};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),exercise={name:f.get('name').trim(),sets:+f.get('sets')||3,reps:f.get('reps').trim()};if(!catalogItem(exercise.name))data.catalog.push({name:exercise.name,group:'Sonstige',sets:exercise.sets,reps:exercise.reps});sessionDraft.exercises.push(exercise);save();d.close();render();toast('Übung hinzugefügt')}}
function saveSession(e){e.preventDefault();const form=e.currentTarget,isFree=form.dataset.free==='true',w=isFree?sessionDraft:data.plan.find(x=>x.id===form.dataset.workout);if(!w){alert('Diese Trainingseinheit ist nicht mehr verfügbar.');return}if(!w.exercises.length){alert('Füge mindestens eine Übung hinzu.');return}const fd=new FormData(form),exercises=w.exercises.map((ex,i)=>({name:ex.name,sets:Array.from({length:+ex.sets||1},(_,j)=>({setNo:j+1,weight:fd.get(`weight-${i}-${j}`),reps:fd.get(`reps-${i}-${j}`)})).filter(set=>set.weight!==''||set.reps!==''),note:fd.get(`note-${i}`)}));for(const used of exercises){let item=catalogItem(used.name);if(!item){item={name:used.name,group:'Sonstige',sets:used.sets.length||3,reps:'8–12'};data.catalog.push(item)}if(used.sets.length){item.sets=used.sets.length;const reps=used.sets.map(set=>+set.reps||0).filter(Boolean);if(reps.length){const lo=Math.min(...reps),hi=Math.max(...reps);item.reps=lo===hi?String(lo):`${lo}–${hi}`}}}const today=new Date(),date=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`,name=isFree?(fd.get('templateName')||'').trim()||w.name:w.name;if(isFree&&fd.get('saveTemplate')==='on')data.plan.push({id:crypto.randomUUID(),name,exercises:w.exercises.map(ex=>({name:ex.name,sets:ex.sets,reps:ex.reps}))});data.history.push({id:crypto.randomUUID(),date,name:w.name,exercises,note:fd.get('note')});save();sessionDraft=null;location.hash='#history';toast('Training gespeichert – stark gemacht!')}
function manualDialog(){const choices=data.plan.map(w=>`<option value="${esc(w.name)}">${esc(w.name)}</option>`).join('');const d=modal(`<h2>Einheit eintragen</h2><p>Ergänze auch vergangene Trainings.</p><form id="manualForm"><div class="field"><label>Einheit</label><select name="name">${choices}<option value="Andere">Andere</option></select></div><div class="field"><label>Datum</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Notiz</label><input name="note" placeholder="Optional"></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">Eintragen</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();$('#manualForm',d).onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.history.push({id:crypto.randomUUID(),date:f.get('date'),name:f.get('name'),exercises:[],note:f.get('note')});save();d.close();render();toast('Einheit eingetragen')};}
function exportData(){const backup={app:'GrevingFit',formatVersion:1,exportedAt:new Date().toISOString(),data};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`grevingfit-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sicherungsdatei heruntergeladen')}
function dataToolsModal(){const d=modal(`<h2>Daten sichern</h2><p>Deine Daten liegen lokal auf diesem Gerät. Exportiere eine vollständige Sicherungsdatei oder stelle eine vorhandene Datei wieder her.</p><div class="grid"><button class="button" type="button" data-export-backup>Sicherung exportieren</button><label class="button secondary" for="importFile">Sicherung importieren</label><input id="importFile" type="file" accept="application/json,.json" hidden></div><p class="tiny muted" style="margin-top:14px">Enthält Plan, Katalog, Verlauf, Satzwerte, Notizen und Spotify-Link.</p>`);$('[data-export-backup]',d).onclick=()=>{d.close();exportData()};$('#importFile',d).onchange=importData}
function importData(e){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),incoming=['GrevingFit','CarstenFit'].includes(parsed?.app)&&parsed?.data?parsed.data:parsed;if(!incoming||!Array.isArray(incoming.plan)||!Array.isArray(incoming.history)||('catalog'in incoming&&!Array.isArray(incoming.catalog)))throw Error();if(!confirm('Der Import ersetzt alle aktuell gespeicherten GrevingFit-Daten auf diesem Gerät. Fortfahren?'))return;data=normalizeData(incoming);save();render();toast('Sicherung auf diesem Gerät wiederhergestellt')}catch{alert('Die Datei ist kein gültiges GrevingFit-Backup. Deine vorhandenen Daten bleiben erhalten.')}finally{e.target.value=''}};reader.readAsText(file)}
localStorage.removeItem('carstenfit-google-client-id-v1');localStorage.removeItem('carstenfit-google-drive-authorized-v1');
