const menuToggle=$('#menuToggle'),menu=$('#appMenu');function setMenu(open){menu.hidden=!open;menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Menü schließen':'Menü öffnen')}menuToggle.onclick=()=>setMenu(menu.hidden);$$('#appMenu a').forEach(link=>link.onclick=()=>setMenu(false));document.addEventListener('click',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!menuToggle.contains(e.target))setMenu(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false)});
window.addEventListener('hashchange',()=>{render();if(!$('#appMenu').hidden)setMenu(false)});render();
window.addEventListener('online',()=>{if(cloudUser)cloudInitialSync()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&cloudUser)cloudInitialSync()});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installBtn').hidden=false});$('#installBtn').onclick=async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installBtn').hidden=true};
